from pathlib import Path
import csv,json
p=Path(__file__).resolve().parent;root=p.parent;s=list(csv.DictReader((p/'summary.csv').open()));paired=json.loads((p/'paired.json').read_text());methods=list(dict.fromkeys(r['method'] for r in s))
labels={'All attributes':'All','Dependency-only':'Dep','Joint guard':'Joint','Cheapest k':'Cheapest k','Correlation k':'Correlation k','Cost-correlation budget':'Cost-corr budget','Forward k':'Forward k','Cost-forward budget':'Positive-only budget','Prediction-only':'Prediction-only','Random k':'Random k','Budget-forward bridge':'Bridge budget'}
md=['# 公平约简基线比较','', '15组原有划分、相同三折与五近邻预测器，原有核心和容差均不修改。新增基线只用训练数据选属性。各重复的测试对象有重叠，结果为描述性配对诊断，不做独立重复显著性推断。','', '## 公平性与对照定义', '', '* 同等属性数：Cheapest k、Random k、Correlation k、Forward k，与联合输出完全同样的k；代价可能不同，必须同时报告。Random k为20次固定随机抽样的平均，不选择最佳抽样。', '* 同代价上限：Cost-correlation budget、Cost-forward budget、Budget-forward bridge，总代价不超过联合输出预算，不要求恰好耗尽；属性数可以不同。', '* Prediction-only是去掉粒球依赖度约束的消融，保留原预测损失阈值和代价权重，不强制匹配属性数或代价。', '* Correlation评分为各属性与每个标签描述度的平方Pearson相关系数之和，常量方差项置零；预算版本用评分/代价排序并跳过超预算属性。这是自定义基础筛选，不是已发表LDL方法的复现。', '* Forward k每次最小化内部Brier，直到恰好k；预算前向版本按内部Brier正下降/代价选择，无法下降则停。', '* 为避免零单属性收益导致预算基线过早停下，保留正增益版本并追加桥接版本：有正增益时用增益/代价，没有正增益时用最大原始有符号增益并以代价和索引打破平局；继续至预算无法加入属性，返回内部损失最小的前缀（包括空集）。这个补充用于前面已证明的属性交互问题；它是在初期基线诊断后追加的描述性扩展，不是未经观察的确认试验。', '', '## 全部结果（五次重复，均值±样本SD）','','|训练数|方法|属性数|模拟代价|外部Brier|','|---:|---|---:|---:|---:|']
tex=[r'\section{Paired reduction-baseline comparisons}',r'\label{sec:baselines}',r'We retain all 15 saved splits, costs, folds, learner and parameters. Baseline selections use training data only and are checkpointed before new test predictions. The test splits have already been inspected in earlier diagnostics, so this is exploratory comparison, not an untouched confirmatory evaluation.',r'\subsection{Matched resources and component controls}',r'Let $k$ and $B$ denote the training-selected joint output cardinality and simulated cost. Cardinality controls select exactly $k$: cheapest attributes, 20 fixed random subsets (average performance, never the best test draw), label-distribution correlation ranking, and sequential forward selection minimizing inner Brier. Their costs may differ and must be reported.',r'The correlation score is $s_a=\sum_{\ell=1}^{q}\operatorname{corr}(x_a,L_\ell)^2$, setting zero-variance terms to zero. A budget filter greedily ranks by $s_a/c(a)$, skipping attributes that exceed remaining budget. A positive-only budget wrapper selects the largest positive inner-loss reduction per unit cost and stops when none is available. Both obey cost at most $B$; cardinality is unconstrained.',r'To address the previously established zero-singleton interaction issue, we retain the positive-only wrapper and additionally run a budget wrapper with nonpositive bridges: positive gains use gain per cost; otherwise the largest signed gain is used with cost/index ties. It exhausts affordable additions and returns the prefix with lowest inner loss, including the empty prefix. This supplement was added after early baseline diagnostics and is a descriptive extension. The prediction-only ablation removes dependency but retains the original loss threshold and cost exponent; its resource usage is unconstrained.',r'These are reproducible generic filters, wrappers and controls, not replicas of named published LDL feature-selection methods. Shared validation reuse can overfit selection for all supervised wrappers. No test result selects a tolerance or a random subset. No full-space optimal-cost or isolated runtime claim is made.',r'\subsection{Results at each training size}']
for n in [192,384,576]:
 tex += [f'\nTraining objects: ${n}$. Test Brier is mean $\\pm$ sample standard deviation over five splits; attributes and cost are means.',r'\begin{center}\small\begin{tabular}{lrrr}\hline',r'Method & Attr. & Cost & Test Brier\\\hline']
 for method in methods:
  r=next(r for r in s if int(r['train_n'])==n and r['method']==method)
  f=lambda key:f"{float(r[key+'_mean']):.4f} ± {float(r[key+'_sd']):.4f}"
  md.append(f"|{n}|{method}|{float(r['attributes_mean']):.1f} ± {float(r['attributes_sd']):.1f}|{float(r['cost_mean']):.1f} ± {float(r['cost_sd']):.1f}|{f('test_brier')}|")
  tex.append(f"{labels[method]} & {float(r['attributes_mean']):.1f} & {float(r['cost_mean']):.1f} & "+f('test_brier').replace(' ± ',r'$\pm$')+r'\\')
 tex += [r'\hline\end{tabular}\end{center}']
md += ['', '## 配对结果：联合−基线', '', '负差值代表联合方法的Brier更低；胜出次数是逐划分比较，不是显著性检验。', '', '|训练数|基线|平均差值|联合胜出|', '|---:|---|---:|---:|']
for d in paired:md.append(f"|{d['train_n']}|{d['baseline']}|{d['joint_minus_baseline_mean']:+.4f}|{d['joint_wins']}/5|")
tex += [r'\begin{figure}[htbp]\centering\includegraphics[width=\linewidth]{baselines/comparison.pdf}',r'\caption{Same-cardinality controls (top), cost-budget controls (middle), and prediction-only component ablation (bottom). Lines show five-split means; full descriptive standard deviations and paired differences are provided with the reproducible results.}\label{fig:baselines}\end{figure}',r'\subsection{Interpretation and limits}']
for method in ['Cheapest k','Random k','Forward k','Cost-correlation budget','Budget-forward bridge','Prediction-only']:
 dd=[d for d in paired if d['baseline']==method];wins=sum(d['joint_wins'] for d in dd);delta=sum(d['joint_minus_baseline_mean'] for d in dd)/3
 tex.append(f"Against {labels[method]}, joint selection has lower test Brier on {wins}/15 splits, with mean paired difference {delta:+.4f} across the three equally weighted training sizes.")
md += ['', '## 具体判断', '', '576对象时，联合Brier为0.2511、代价17.4，强预算桥接基线为0.2510、16.6，均值几乎相同；联合逐划分仅胜出2/5。相比同属性数前向选择，联合均值更低且成本更低，但同样仅胜出2/5，不能解释为稳定优势。三个规模合计联合优于桥接基线9/15、优于Prediction-only 7/15。', '', '## 结论边界', '', '这些对照只能评价当前单数据集、固定五近邻预测器和模拟代价下的表现；不能据此宣称优于最新已发表LDL约简方法。需要结合实际资源使用判断：同属性数前向选择通常花费更高代价，同预算方法可能选不同数量属性。', '', 'Prediction-only若优于联合方法，就不能把当前结果解释为粒球依赖度的普遍增益；两者搜索路径也不同，不能单靠一次对照确定因果机制。', '', '原始数据和四项指标（Brier、KL、TV、JS）见results.csv、summary.csv；每个划分保留选取检查点、20次随机抽样指标和搜索轨迹。复现顺序：run_baselines.py → run_bridge.py → summarize.py → write_report.py。']
tex += [r'At $n=576$, joint selection and the bridge-budget wrapper have almost identical mean test Brier (0.2511 versus 0.2510), while the wrapper uses mean cost 16.6 versus 17.4 and mean cardinality 8.6 versus 12.6. Joint wins only two of these five paired splits. Thus this experiment does not establish an irreplaceable benefit of the dependency constraint.',r'Interpretation must account for the actual resource usage: matched-cardinality forward selection can cost more, while budget controls can select a different number of attributes. The prediction-only ablation also changes the search path, so an outcome cannot by itself establish a causal granular-ball contribution. These single-dataset, fixed-predictor, simulated-cost diagnostics do not establish superiority over published LDL reduction methods.']
(p/'BASELINE_REPORT.md').write_text('\n'.join(md)+'\n');(root/'section_8_baselines.tex').write_text('\n'.join(tex)+'\n')
main=root/'ASC_LDL_foundations.tex';text=main.read_text()
if '\\input{section_8_baselines.tex}' not in text:main.write_text(text.replace('\\input{section_7_stability.tex}','\\input{section_7_stability.tex}\n\\input{section_8_baselines.tex}'))
